{
  "title": "update-404-error-message",
  "request": "the 404 error message is confusing, can we change it to a clearer 'Not found. Please check your request.' instead of the generic internal error text?",
  "edits": [
    {
      "path": "langfuse/_utils/parse_error.py",
      "search": "404: f"Internal error occurred. {defaultServerErrorPrompt}",",
      "replace": "404: "Not found. Please check your request.","
    }
  ],
  "test_path": "tests/unit/test_parse_error_message.py",
  "test": "import pytest
from langfuse._utils.parse_error import generate_error_message_fern
from langfuse.api.core import ApiError

class DummyError(ApiError):
    def __init__(self, status_code: int):
        # Bypass ApiError's init; only status_code is needed for generate_error_message_fern
        self.status_code = status_code
        self.headers = {}
        self.body = ""

def test_404_error_message_is_updated():
    err = DummyError(404)
    msg = generate_error_message_fern(err)
    assert msg == "Not found. Please check your request."
"
}
